# Code generated by Claude
"""
Tests of the support chain and the stance method choice (src/support.py, addendum G, decisions-log M174) on made-up world models; no simulator.

    python experiments/support_test.py

1. The beaker's chain is beaker, hotplate, bench with the expected target height (and the place's, and the beaker on the bench).
2. An object on a made-up 20 cm box on the bench gets the raised height.
3. A phrase with no chain stops with "surface unknown: <phrase>".
4. An object above the reach band stops with "target height outside the reach band: ...".
5. A chain that loops stops with "support chain does not end at a surface: <entry>".
6. An object raised beyond bench_max_raise_m stops with "no stance method: ...".
7. The test scene's place is inside the band, a root with no settings stops, held steps have the surface "held" and the runs group only the same surface.
"""

import copy
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.support import SupportError, band_points, check_band, is_null_step, same_surface_runs, stance_method, step_support  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, PICK_PLACE_CFG  # noqa: E402
from src.world_model import Entry, WorldModel  # noqa: E402

results = []
TOP = 0.96


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def E(id, kind="object", **props):
    return Entry(id, id, (id,), kind, np.zeros(3), None, props)


def scene(beaker_on="bench"):
    w = WorldModel()
    w.upsert(E("bench", "fixture", top_z=TOP, top_z_known=True, surface=True))
    w.upsert(E("hotplate", "fixture", supported_by="bench", height=0.068))
    w.upsert(E("beaker", height=0.10, held_by=None, supported_by=beaker_on))
    return w


def stop(fn):
    try:
        fn()
    except SupportError as e:
        return str(e)
    return None


def main():
    frac, gap = PICK_PLACE_CFG["grasp_height_frac"], PICK_PLACE_CFG["setdown_gap_m"]
    print("\n1. the beaker's chain")
    w = scene("hotplate")
    i = step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker")
    check("beaker on the hotplate: chain beaker, hotplate, bench; surface bench; target height = bench top + hotplate + the grasp fraction of the beaker", i["support_chain"] == ["beaker", "hotplate", "bench"]
          and i["surface"] == "bench" and abs(i["target_height"] - (TOP + 0.068 + frac * 0.10)) < 1e-9, f"{i}")
    w = scene("bench")
    i = step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker")
    check("the test scene's pick (the beaker starts on the bench): chain beaker, bench; target = bench top + grasp fraction", i["support_chain"] == ["beaker", "bench"] and abs(i["target_height"] - (TOP + frac * 0.10)) < 1e-9, f"{i['target_height']:.4f}")
    w.get("beaker").properties["held_by"] = "left"
    i = step_support(w, "place", {"manipulated": w.get("beaker"), "destination": w.get("hotplate")}, "the hotplate")
    check("the place: the destination's chain (hotplate, bench), the beaker's base on the hotplate's top (+ the set-down gap)", i["support_chain"] == ["hotplate", "bench"] and abs(i["target_height"] - (TOP + 0.068 + gap + frac * 0.10)) < 1e-9, f"{i['target_height']:.4f}")
    place_info = i

    print("\n2. an object on a 20 cm box")
    w = scene("box")
    w.upsert(E("box", "fixture", supported_by="bench", height=0.20))
    i = step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker")
    check("the raised height: bench top + 0.20 + the grasp fraction", i["support_chain"] == ["beaker", "box", "bench"] and abs(i["target_height"] - (TOP + 0.20 + frac * 0.10)) < 1e-9, f"{i['target_height']:.4f}")

    print("\n3. no chain")
    w = scene("bench")
    w.get("beaker").properties.pop("supported_by")
    msg = stop(lambda: step_support(w, "pick", {"manipulated": w.get("beaker")}, "the green flask"))
    check("a phrase whose entry has no support stops with 'surface unknown: <phrase>'", msg == "surface unknown: the green flask", f"{msg!r}")

    print("\n4. above the reach band")
    w = scene("box")
    w.upsert(E("box", "fixture", supported_by="bench", height=0.60))
    i = step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker")
    msg = stop(lambda: check_band(i, "the beaker", band=(0.90, 1.30)))
    check("stops with the target height and the band", msg is not None and msg == f"target height outside the reach band: the beaker at {i['target_height']:.3f} m, band 0.900 to 1.300 m", f"{msg!r}")
    check("a height inside the band does not stop", stop(lambda: check_band(place_info, "the hotplate", band=(0.90, 1.30))) is None)

    print("\n5. a loop")
    w = scene("hotplate")
    w.get("hotplate").properties["supported_by"] = "beaker"
    msg = stop(lambda: step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker"))
    check("beaker on hotplate on beaker stops with 'support chain does not end at a surface'", msg is not None and msg.startswith("support chain does not end at a surface: "), f"{msg!r}")
    w = scene("gone")
    msg = stop(lambda: step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker"))
    check("a support that is not in the world model also stops", msg == "support chain does not end at a surface: gone", f"{msg!r}")

    print("\n6. raised beyond bench_max_raise_m")
    cfg = {**copy.deepcopy(BENCH_STANCE_CFG), "bench_max_raise_m": 0.15}
    w = scene("box")
    w.upsert(E("box", "fixture", supported_by="bench", height=0.20))
    i = step_support(w, "pick", {"manipulated": w.get("beaker")}, "the beaker")
    msg = stop(lambda: stance_method(i, w, "the beaker", cfg))
    check("stops with the raise and the limit", msg == f"no stance method: the beaker is {i['target_height'] - TOP:.3f} m above the bench top, limit 0.150 m" and abs(i["target_height"] - TOP - (0.20 + frac * 0.10)) < 1e-9, f"{msg!r}")

    print("\n7. the test scene, roots, held steps and runs")
    w = scene("bench")
    w.get("beaker").properties["held_by"] = "left"
    cfg = {**copy.deepcopy(BENCH_STANCE_CFG), "bench_max_raise_m": 0.20}
    m = stance_method(place_info, w, "the hotplate", cfg)
    check("the test scene's place is inside the band", m["method"] == "bench" and abs(m["raise_m"] - (0.068 + gap + frac * 0.10)) < 1e-9, f"raise {m['raise_m']:.4f} m against limit {cfg['bench_max_raise_m']}")
    check("a surface root with no settings stops with 'no stance method for surface: <name>'", stop(lambda: stance_method({**place_info, "surface": "cabinet"}, w, "the shelf", cfg)) == "no stance method for surface: cabinet")
    w = scene("bench")
    w.get("beaker").properties["held_by"] = "left"
    h = step_support(w, "other", {"manipulated": w.get("beaker")}, "the beaker")
    check("an object in the hand with no destination has the surface 'held'", h["surface"] == "held" and h["target_height"] is None, f"{h}")
    check("'held' has no stance method", stop(lambda: stance_method(h, w, "the beaker", cfg)) == "no stance method for surface: held")
    infos = [{"surface": "bench"}, {"surface": "bench"}, {"surface": "cabinet"}, {"surface": "bench"}, {"surface": "bench"}]
    check("runs group only consecutive steps with the same root surface", same_surface_runs(infos, 0) == [0, 1] and same_surface_runs(infos, 2) == [2] and same_surface_runs(infos, 3) == [3, 4]
          and same_surface_runs([{"surface": "bench"}] * 6, 0, kmax=4) == [0, 1, 2, 3] and same_surface_runs([{"surface": "held"}, {"surface": "held"}], 0) == [0])
    check("the null step needs the same root surface", is_null_step("bench", "bench") and not is_null_step("cabinet", "bench") and not is_null_step("bench", None) and not is_null_step("held", "held"))
    bp = band_points(1.0125, 0.10, (0.45, 0.60))
    check("band_points: the band's fractions around the grasp point (45 to 60 % of 10 cm, middle 52.5 %)", np.allclose(bp, [1.0125 + (f - 0.525) * 0.10 for f in (0.45, 0.50, 0.55, 0.60)]), f"{np.round(bp, 4).tolist()}")

    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
